import numpy as np
import scipy.linalg
import time
import sys
sys.path.insert(0, '/app')
import warnings
warnings.filterwarnings('ignore', category=DeprecationWarning)

def sqrtm_2x2(A):
    """Closed-form principal square root for 2x2 matrix."""
    # Ensure complex
    A = np.asarray(A, dtype=complex)
    a, b = A[0, 0], A[0, 1]
    c, d = A[1, 0], A[1, 1]
    # Compute trace and determinant
    tr = a + d
    det = a * d - b * c
    # Compute eigenvalues of A
    # lambda1,2 = (tr ± sqrt(tr^2 - 4*det))/2
    disc = np.sqrt(tr**2 - 4*det)
    lam1 = (tr + disc) / 2
    lam2 = (tr - disc) / 2
    # Compute sqrt of eigenvalues with non-negative real part
    sqrt_lam1 = np.sqrt(lam1)
    if sqrt_lam1.real < 0:
        sqrt_lam1 = -sqrt_lam1
    sqrt_lam2 = np.sqrt(lam2)
    if sqrt_lam2.real < 0:
        sqrt_lam2 = -sqrt_lam2
    # Compute square root matrix using Sylvester's formula
    # If eigenvalues are distinct
    if abs(lam1 - lam2) > 1e-12:
        # X = (sqrt_lam1 * (A - lam2*I) - sqrt_lam2 * (A - lam1*I)) / (lam1 - lam2)
        I = np.eye(2, dtype=complex)
        X = (sqrt_lam1 * (A - lam2 * I) - sqrt_lam2 * (A - lam1 * I)) / (lam1 - lam2)
    else:
        # Repeated eigenvalue: use derivative
        # X = sqrt_lam1 * (I + (A - lam1*I) / (2*lam1))
        # Actually, for repeated eigenvalue, the formula is more involved.
        # Use scipy.linalg.sqrtm for safety.
        X, _ = scipy.linalg.sqrtm(A, disp=False)
    return X

def solve_current(problem):
    A = problem['matrix']
    if not isinstance(A, np.ndarray):
        A = np.array(A, dtype=complex)
    if A.ndim != 2 or A.shape[0] != A.shape[1]:
        return {'sqrtm': {'X': []}}
    try:
        X, _ = scipy.linalg.sqrtm(A, disp=False, blocksize=2)
    except:
        return {'sqrtm': {'X': []}}
    return {'sqrtm': {'X': X.tolist()}}

def solve_optimized(problem):
    A = problem['matrix']
    # Convert to numpy array if not already, using asarray to avoid copy if possible
    if not isinstance(A, np.ndarray):
        A = np.asarray(A, dtype=complex)
    else:
        # Ensure dtype is complex
        if A.dtype != complex:
            A = A.astype(complex)
    if A.ndim != 2 or A.shape[0] != A.shape[1]:
        return {'sqrtm': {'X': []}}
    n = A.shape[0]
    if n == 2:
        X = sqrtm_2x2(A)
    else:
        try:
            X, _ = scipy.linalg.sqrtm(A, disp=False, blocksize=2)
        except:
            return {'sqrtm': {'X': []}}
    return {'sqrtm': {'X': X.tolist()}}

# Generate random matrices of various sizes
np.random.seed(42)
sizes = [2, 5, 10, 20, 50, 100]
for n in sizes:
    A = np.random.randn(n, n) + 1j * np.random.randn(n, n)
    problem = {'matrix': A.tolist()}
    # Time current
    runs = 100 if n <= 10 else 10
    start = time.time()
    for _ in range(runs):
        sol1 = solve_current(problem)
    current_time = (time.time() - start) / runs
    # Time optimized
    start = time.time()
    for _ in range(runs):
        sol2 = solve_optimized(problem)
    optimized_time = (time.time() - start) / runs
    # Check solutions are same
    X1 = np.array(sol1['sqrtm']['X'], dtype=complex)
    X2 = np.array(sol2['sqrtm']['X'], dtype=complex)
    max_diff = np.max(np.abs(X1 - X2))
    print(f'n={n}: current={current_time:.6f}s, optimized={optimized_time:.6f}s, speedup={current_time/optimized_time:.2f}x, max_diff={max_diff:.2e}')
